import {HOME_STATIONS} from './home-layout.js';
export const INGREDIENTS={rice:{name:'Rice',store:'cupboard'},tomato:{name:'Tomatoes',store:'fridge'},beans:{name:'Beans',store:'cupboard'},plantain:{name:'Plantain',store:'cupboard'}};
export const RECIPES={jollof:{name:'Jollof rice',needs:{rice:1,tomato:1},meal:'home-jollof'},beans:{name:'Beans & plantain',needs:{beans:1,plantain:1},meal:'home-beans'}};
export const NUTRITION={'pepper-yam':{name:'Pepper yam takeaway',food:55,mood:10},jollof:{name:'Jollof & plantain',food:65,mood:8},beans:{name:'Beans & plantain',food:55,mood:6},'home-jollof':{name:'Home-cooked jollof',food:65,mood:10},'home-beans':{name:'Home-cooked beans & plantain',food:60,mood:10},'practice-rice':{name:'Practice rice plate',food:30,mood:2}};
const ok=message=>({ok:true,message}),no=message=>({ok:false,message});
export const mealAlive=m=>!['consumed','discarded'].includes(m.phase);
export const activeMeals=s=>s.daily.meals.filter(mealAlive);
export const heldMeal=s=>activeMeals(s).find(m=>m.phase==='carried');
export const tableMeal=s=>activeMeals(s).find(m=>m.place==='table'&&['placed','opened','partly-eaten'].includes(m.phase));
export const kitchenActive=s=>s.homeLife?.job&&!['done','cancelled'].includes(s.homeLife.job.stage);
export function normaliseMeal(m){return {...m,phase:m.phase||'stored',place:m.place||'bag',bites:m.bites||0,opened:!!m.opened};}
export function newMeal(s,id,recipe,{carry=false,place='table'}={}){if(s.daily.meals.some(m=>m.id===id))return false;s.daily.meals=s.daily.meals.filter(m=>mealAlive(m)||s.daily.meals.indexOf(m)>=s.daily.meals.length-40);s.daily.meals.push({id,recipe,phase:carry?'carried':place==='table'?'placed':'stored',place:carry?'hand':place,bites:0,opened:false});return true;}
export function migrateHomeLife(s,data){s.daily.meals=s.daily.meals.map(normaliseMeal);s.homeLife=data?.homeLife?structuredClone(data.homeLife):{version:1,stockSerial:0,ingredients:{bag:{rice:0,tomato:0,beans:0,plantain:0},fridge:{rice:0,tomato:0,beans:0,plantain:0},cupboard:{rice:0,tomato:0,beans:0,plantain:0}},job:null};
 if(!data?.homeLife&&['prep','simmer'].includes(s.daily.cook?.status)){const c=s.daily.cook;s.homeLife.job={id:c.id,recipe:'jollof',stage:c.status==='prep'?'prepare':'cook',reserved:{rice:1,tomato:1},origins:{rice:'bag',tomato:'bag'},spent:c.status==='simmer',chops:c.chops,heat:c.heat,burner:c.burner,elapsed:c.elapsed,green:c.good,stirs:c.stirs,sinceStir:c.sinceStir};c.status='cancelled';}
}
export function validHomeLife(h){if(h===undefined)return true;if(!h||h.version!==1||!Number.isSafeInteger(h.stockSerial)||h.stockSerial<0||!h.ingredients)return false;for(const place of ['bag','fridge','cupboard'])if(!h.ingredients[place]||!Object.keys(INGREDIENTS).every(k=>Number.isInteger(h.ingredients[place][k])&&h.ingredients[place][k]>=0&&h.ingredients[place][k]<=999))return false;const j=h.job;if(j===null)return true;return !!j&&Number.isSafeInteger(j.id)&&j.id>0&&Object.hasOwn(RECIPES,j.recipe)&&['collect','prepare','cook','plate','done','cancelled'].includes(j.stage)&&typeof j.spent==='boolean'&&j.reserved&&j.origins&&Object.entries(j.reserved).every(([k,n])=>RECIPES[j.recipe].needs[k]===n&&['bag','fridge','cupboard'].includes(j.origins[k]))&&['chops','heat','burner','elapsed','green','stirs','sinceStir'].every(k=>Number.isFinite(j[k])&&j[k]>=0&&j[k]<=100)&&Number.isInteger(j.chops)&&j.chops<=3&&Number.isInteger(j.stirs);}
export function validPhysicalMeal(m){return m.phase===undefined||(['carried','placed','opened','partly-eaten','stored','consumed','discarded'].includes(m.phase)&&['hand','table','bag','fridge'].includes(m.place)&&Number.isInteger(m.bites)&&m.bites>=0&&m.bites<=4&&typeof m.opened==='boolean'&&(m.phase!=='consumed'||m.bites===4)&&(!['placed','opened','partly-eaten'].includes(m.phase)||m.place==='table')&&(m.phase!=='carried'||m.place==='hand')&&(m.phase!=='stored'||['bag','fridge'].includes(m.place))&&(!mealAlive(m)||m.bites<4));}
function at(location,position,id){const p=HOME_STATIONS[id]?.stand;return location==='home'&&p&&Math.hypot(position.x-p.x,position.z-p.z)<1.2;}
export function carryMeal(s,id,location,position){const m=s.daily.meals.find(m=>m.id===id);if(!m||!mealAlive(m))return no('That meal is no longer available.');if(heldMeal(s))return no('Place or store the meal in your hand first.');if(m.place==='table'&&!at(location,position,'table')||m.place==='fridge'&&!at(location,position,'fridge'))return no('Approach the meal first.');m.phase='carried';m.place='hand';return ok('Meal in hand. Carry it to the dining table.');}
export function placeMeal(s,id,location,position){const m=heldMeal(s);if(m?.serviceOrder)return no('Serve this plate to the customer at Mama T’s.');if(!m||m.id!==id||!at(location,position,'table'))return no('Carry the meal to the table.');if(tableMeal(s))return no('Store or finish the meal already on the table.');m.phase=m.bites?'partly-eaten':m.opened?'opened':'placed';m.place='table';return ok('Meal placed on the table.');}
export function openMeal(s,id,location,position){const m=tableMeal(s);if(!m||m.id!==id||m.opened||!at(location,position,'table'))return no('Approach the unopened meal on the table.');m.opened=true;m.phase='opened';return ok('Meal opened. Enjoy your meal.');}
export function biteMeal(s,id,expected,location,position){const m=tableMeal(s);if(!m||m.id!==id||!m.opened||m.bites!==expected||m.bites>=4||!at(location,position,'table'))return no('This bite was already handled, or the meal is not ready.');if(s.food>=100)return no('You are full. Keep the leftovers.');const n=NUTRITION[m.recipe];m.bites++;s.food=Math.min(100,s.food+n.food/4);s.mood=Math.min(100,s.mood+n.mood/4);m.phase=m.bites===4?'consumed':'partly-eaten';if(m.bites===4)s.daily.stats.eaten++;return ok(m.bites===4?'Meal finished.':'Bite '+m.bites+' of 4. Leftovers stay on the table.');}
export function storeMeal(s,id,place,location,position){const m=s.daily.meals.find(m=>m.id===id);if(m?.serviceOrder)return no('This plate belongs to a customer. Serve it or cancel the order.');if(!m||!mealAlive(m)||!['bag','fridge'].includes(place))return no('Choose an available meal.');if(place==='fridge'&&!at(location,position,'fridge'))return no('Approach the fridge to store leftovers.');if(m.place==='table'&&!at(location,position,'table'))return no('Take the meal from the table first.');m.phase='stored';m.place=place;return ok('Meal deliberately stored in '+(place==='bag'?'your bag':'the fridge')+'.');}
export function discardMeal(s,id){const m=s.daily.meals.find(m=>m.id===id);if(!m||!mealAlive(m))return no('Already removed.');m.phase='discarded';return ok('Meal discarded. No food reward.');}
export function unpackGroceries(s,recipe,serial){if(serial!==s.homeLife.stockSerial||!RECIPES[recipe]||s.pantry<1)return no('No unopened grocery portion available, or already handled.');const needs=RECIPES[recipe].needs;if(Object.keys(needs).some(k=>s.homeLife.ingredients.bag[k]>=999))return no('Ingredient bag full.');s.pantry--;s.homeLife.stockSerial++;for(const [k,n] of Object.entries(needs))s.homeLife.ingredients.bag[k]+=n;return ok('Unpacked ingredients into your bag. Store them at the fridge/cupboard.');}
export function moveIngredient(s,key,from,to,serial,location,position){if(serial!==s.homeLife.stockSerial||!INGREDIENTS[key]||!['bag','fridge','cupboard'].includes(from)||!['bag',INGREDIENTS[key].store].includes(to)||from===to||!s.homeLife.ingredients[from][key])return no('That transfer was already handled or is not suitable.');const station=from==='bag'?to:from;if(!at(location,position,station))return no('Approach the storage cabinet first.');if(s.homeLife.ingredients[to][key]>=999)return no('Storage full.');s.homeLife.ingredients[from][key]--;s.homeLife.ingredients[to][key]++;s.homeLife.stockSerial++;return ok(INGREDIENTS[key].name+' moved to '+to+'.');}
export function recipeAvailability(s,id){return Object.entries(RECIPES[id].needs).map(([key,n])=>({key,name:INGREDIENTS[key].name,need:n,have:['bag','fridge','cupboard'].reduce((sum,p)=>sum+s.homeLife.ingredients[p][key],0)}));}
export function beginRecipe(s,id,serial,location,position){if(heldMeal(s))return no('Place or store the carried meal first.');if(kitchenActive(s)||serial!==s.daily.cookSerial||!RECIPES[id]||!at(location,position,'prep'))return no('Choose a recipe at the preparation counter.');if(s.daily.cookSerial>=1e9)return no('Recipe limit reached.');if(activeMeals(s).length>=20)return no('Meal storage is full.');if(recipeAvailability(s,id).some(i=>i.have<i.need))return no('Collect the missing groceries first.');s.homeLife.job={id:++s.daily.cookSerial,recipe:id,stage:'collect',reserved:{},origins:{},spent:false,chops:0,heat:35,burner:65,elapsed:0,green:0,stirs:0,sinceStir:2};return ok('Recipe selected. Collect each ingredient from its storage.');}
export function collectIngredient(s,id,key,from,location,position){const j=s.homeLife.job;if(!j||j.id!==id||j.stage!=='collect'||j.reserved[key]||!RECIPES[j.recipe].needs[key]||!['bag','fridge','cupboard'].includes(from))return no('Ingredient already collected or not required.');if(!at(location,position,from==='bag'?'prep':from)||s.homeLife.ingredients[from][key]<1)return no('Approach the correct storage with that ingredient.');s.homeLife.ingredients[from][key]--;j.reserved[key]=1;j.origins[key]=from;s.homeLife.stockSerial++;if(Object.keys(RECIPES[j.recipe].needs).every(k=>j.reserved[k]))j.stage='prepare';return ok(j.stage==='prepare'?'Ingredients collected. Prepare at the counter.':'Ingredient collected.');}
export function prepareRecipe(s,id,expected,location,position){const j=s.homeLife.job;if(!j||j.id!==id||j.stage!=='prepare'||j.chops!==expected||!at(location,position,'prep'))return no('That preparation was already handled.');j.spent=true;j.chops++;if(j.chops===3)j.stage='cook';return ok(j.stage==='cook'?'Prepared. Move to the cooker.':'Preparation '+j.chops+' of 3.');}
export function heatRecipe(s,dt){const j=s.homeLife.job;if(j?.stage!=='cook')return;dt=Math.max(0,Math.min(.05,dt));j.heat+=(j.burner-j.heat)*dt*.5;j.elapsed=Math.min(100,j.elapsed+dt);j.sinceStir=Math.min(100,j.sinceStir+dt);if(j.heat>=55&&j.heat<=75)j.green=Math.min(100,j.green+dt);}
export function stirRecipe(s,id,expected,location,position){const j=s.homeLife.job;if(!j||j.id!==id||j.stage!=='cook'||j.stirs!==expected||j.sinceStir<2||!at(location,position,'cook'))return no('Wait two seconds before the next stir.');j.stirs=Math.min(100,j.stirs+1);j.sinceStir=0;return ok('Stirred.');}
export function finishRecipeHeat(s,id,location,position){const j=s.homeLife.job;if(!j||j.id!==id||j.stage!=='cook'||j.elapsed<8||j.green<2||j.stirs<2||!at(location,position,'cook'))return no('Simmer 8 seconds, hold green heat 2 seconds and stir twice.');j.stage='plate';return ok('Cooked. Plate at the preparation counter.');}
export function plateRecipe(s,id,location,position){const j=s.homeLife.job;if(!j||j.id!==id||j.stage!=='plate'||(!at(location,position,'prep')&&!at(location,position,'cook')))return no('Plate this recipe at the counter.');if(heldMeal(s))return no('Place or store the meal in your hand first.');if(!newMeal(s,'cook-'+j.id,RECIPES[j.recipe].meal,{carry:true}))return no('Already plated.');s.daily.meals.find(m=>m.id==='cook-'+j.id).opened=true;j.stage='done';s.daily.stats.cooked++;s.stats.cooked++;s.skills.chef++;return {...ok(RECIPES[j.recipe].name+' ready — plate in your right hand. Eat at the dining table.'),minutes:30};}
export function cancelRecipe(s,id){const j=s.homeLife.job;if(!j||j.id!==id||!kitchenActive(s))return no('Recipe already settled.');if(!j.spent&&Object.entries(j.reserved).some(([k,n])=>s.homeLife.ingredients[j.origins[k]][k]+n>999))return no('Make room in ingredient storage before cancelling.');if(!j.spent){for(const [k,n] of Object.entries(j.reserved))s.homeLife.ingredients[j.origins[k]][k]+=n;s.homeLife.stockSerial++;}j.stage='cancelled';return ok(j.spent?'Recipe discarded after preparation. Ingredients used.':'Recipe cancelled. Collected ingredients returned.');}
